<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class QuestionController extends Controller{public function index(Request $r){return DB::table('product_questions')->join('products','products.id','=','product_questions.product_id')->join('users','users.id','=','product_questions.user_id')->select('product_questions.*','products.title as product_title','users.name as user_name','users.mobile')->when($r->status,fn($q,$v)=>$q->where('product_questions.status',$v))->latest('product_questions.created_at')->paginate(25);}public function answer(Request $r,int $question){$data=$r->validate(['answer'=>'required|string|min:2|max:2000','status'=>'required|in:approved,rejected']);abort_unless(DB::table('product_questions')->where('id',$question)->update($data+['answered_by'=>$r->user()->id,'answered_at'=>now(),'updated_at'=>now()]),404);return DB::table('product_questions')->find($question);}public function destroy(int $question){DB::table('product_questions')->where('id',$question)->delete();return response()->noContent();}}
